examples.code:
#include <bit>
#include <bitset>
#include <cstdint>
#include <iostream>

static_assert(std::popcount(0xFULL) == 4);

int main() {
    for (const std::uint8_t x : {0, 0b00011101, 0b11111111})
        std::cout << "popcount( " << std::bitset<8>(x) << " ) = " << std::popcount(x)
                  << '\n';
}

